      <PasscodeModal
         isOpen={passcodeModal.isOpen}
         actionKey={passcodeModal.actionKey}
         actionName={passcodeModal.actionName}
         isDark={isDark}
         onClose={() => setPasscodeModal(prev => ({ ...prev, isOpen: false }))}
